// Pointer lock for web pages on Wayland: see pointerlock.h.
#include "pointerlock.h"

#include <QCursor>
#include <QGuiApplication>
#include <QKeyEvent>
#include <QWindow>
#include <QtGui/qguiapplication_platform.h>

#include <wayland-client.h>

// The protocols' code (generated by wayland-scanner from the XML beside it;
// cpp/wayland/README). (Its hidden visibility comes after a declaration, which
// C++ compilers warn about; it doesn't matter in an executable.)
extern "C" {
#pragma GCC diagnostic push
#pragma GCC diagnostic ignored "-Wattributes"
#include "wayland/pointer-constraints-unstable-v1-protocol.c"
#include "wayland/relative-pointer-unstable-v1-protocol.c"
#pragma GCC diagnostic pop
#include "wayland/pointer-constraints-unstable-v1-client-protocol.h"
#include "wayland/relative-pointer-unstable-v1-client-protocol.h"
}

namespace {

// Kite's own wl_pointer, for the surface the pointer is over: the one to lock.
// (Qt's is Qt's, with its own listener.) Every event needs a function.
void pEnter(void *data, wl_pointer *, uint32_t, wl_surface *surface, wl_fixed_t, wl_fixed_t)
{
    static_cast<PointerLock *>(data)->pointerEntered(surface);
}
void pLeave(void *data, wl_pointer *, uint32_t, wl_surface *surface) { static_cast<PointerLock *>(data)->pointerLeft(surface); }
void pMotion(void *, wl_pointer *, uint32_t, wl_fixed_t, wl_fixed_t) {}
void pButton(void *, wl_pointer *, uint32_t, uint32_t, uint32_t, uint32_t) {}
void pAxis(void *, wl_pointer *, uint32_t, uint32_t, wl_fixed_t) {}
void pFrame(void *, wl_pointer *) {}
void pAxisSource(void *, wl_pointer *, uint32_t) {}
void pAxisStop(void *, wl_pointer *, uint32_t, uint32_t) {}
void pAxisDiscrete(void *, wl_pointer *, uint32_t, int32_t) {}
#ifdef WL_POINTER_AXIS_VALUE120_SINCE_VERSION
void pAxisValue120(void *, wl_pointer *, uint32_t, int32_t) {}
#endif
#ifdef WL_POINTER_AXIS_RELATIVE_DIRECTION_SINCE_VERSION
void pAxisRelativeDirection(void *, wl_pointer *, uint32_t, uint32_t) {}
#endif
#ifdef WL_POINTER_WARP_SINCE_VERSION
void pWarp(void *, wl_pointer *, wl_fixed_t, wl_fixed_t) {}
#endif

wl_pointer_listener pointerListener()
{
    wl_pointer_listener l{};
    l.enter = pEnter;
    l.leave = pLeave;
    l.motion = pMotion;
    l.button = pButton;
    l.axis = pAxis;
    l.frame = pFrame;
    l.axis_source = pAxisSource;
    l.axis_stop = pAxisStop;
    l.axis_discrete = pAxisDiscrete;
#ifdef WL_POINTER_AXIS_VALUE120_SINCE_VERSION
    l.axis_value120 = pAxisValue120;
#endif
#ifdef WL_POINTER_AXIS_RELATIVE_DIRECTION_SINCE_VERSION
    l.axis_relative_direction = pAxisRelativeDirection;
#endif
#ifdef WL_POINTER_WARP_SINCE_VERSION
    l.warp = pWarp;
#endif
    return l;
}
const wl_pointer_listener s_pointerListener = pointerListener();

void rGlobal(void *data, wl_registry *registry, uint32_t name, const char *interface, uint32_t version)
{
    static_cast<PointerLock *>(data)->global(registry, name, interface, version);
}
void rGlobalRemove(void *, wl_registry *, uint32_t) {}
const wl_registry_listener s_registryListener = {rGlobal, rGlobalRemove};

void lLocked(void *data, zwp_locked_pointer_v1 *) { static_cast<PointerLock *>(data)->lockActivated(); }
void lUnlocked(void *data, zwp_locked_pointer_v1 *) { static_cast<PointerLock *>(data)->lockDeactivated(); }
const zwp_locked_pointer_v1_listener s_lockedListener = {lLocked, lUnlocked};

void relMotion(void *data, zwp_relative_pointer_v1 *, uint32_t, uint32_t, wl_fixed_t dx, wl_fixed_t dy, wl_fixed_t dxRaw, wl_fixed_t dyRaw)
{
    static_cast<PointerLock *>(data)->relativeMotion(wl_fixed_to_double(dx), wl_fixed_to_double(dy), wl_fixed_to_double(dxRaw), wl_fixed_to_double(dyRaw));
}
const zwp_relative_pointer_v1_listener s_relativeListener = {relMotion};

} // namespace

PointerLock::PointerLock(QObject *parent)
    : QObject(parent)
{
    // Movement goes to the page about as often as the screen refreshes, or
    // faster: what came in meanwhile is added up.
    m_flush.setSingleShot(true);
    m_flush.setInterval(4);
    connect(&m_flush, &QTimer::timeout, this, &PointerLock::flush);
    m_timeout.setSingleShot(true);
    m_timeout.setInterval(1500);
    connect(&m_timeout, &QTimer::timeout, this, [this] { end(QStringLiteral("The mouse pointer couldn't be locked.")); });
    // Early, so Kite's wl_pointer sees the pointer enter a window before a page asks.
    setUp();
}

PointerLock::~PointerLock()
{
    end(QString());
    if (m_relativeManager) zwp_relative_pointer_manager_v1_destroy(m_relativeManager);
    if (m_constraints) zwp_pointer_constraints_v1_destroy(m_constraints);
    if (m_pointer) wl_pointer_destroy(m_pointer);
}

QString PointerLock::setUp()
{
    if (m_setUp) return m_unavailable;
    if (!QGuiApplication::platformName().startsWith(QLatin1String("wayland"))) {
        // (Not cached: nothing changes, but the message is cheap.)
        return QStringLiteral("Kite can lock the mouse pointer only in a Wayland session.");
    }
    auto *wayland = qGuiApp->nativeInterface<QNativeInterface::QWaylandApplication>();
    if (!wayland || !wayland->display() || !wayland->seat())
        return QStringLiteral("Kite can't reach the Wayland compositor.");
    // Asking for a pointer from a seat that never had one is a protocol error:
    // wait until Qt has one.
    if (!wayland->pointer()) return QStringLiteral("There is no mouse.");
    m_setUp = true;

    // The globals, on a queue of Kite's own (Qt reads the default one in
    // another thread), then moved to the default queue, which Qt dispatches
    // on this thread.
    wl_display *display = wayland->display();
    wl_event_queue *queue = wl_display_create_queue(display);
    auto *wrapped = static_cast<wl_display *>(wl_proxy_create_wrapper(display));
    wl_proxy_set_queue(reinterpret_cast<wl_proxy *>(wrapped), queue);
    wl_registry *registry = wl_display_get_registry(wrapped);
    wl_proxy_wrapper_destroy(wrapped);
    wl_registry_add_listener(registry, &s_registryListener, this);
    wl_display_roundtrip_queue(display, queue);
    wl_registry_destroy(registry);
    if (m_constraints) wl_proxy_set_queue(reinterpret_cast<wl_proxy *>(m_constraints), nullptr);
    if (m_relativeManager) wl_proxy_set_queue(reinterpret_cast<wl_proxy *>(m_relativeManager), nullptr);
    wl_event_queue_destroy(queue);

    if (!m_constraints || !m_relativeManager) {
        m_unavailable = QStringLiteral("This desktop doesn't let apps lock the mouse pointer.");
        return m_unavailable;
    }
    m_pointer = wl_seat_get_pointer(wayland->seat());
    wl_pointer_add_listener(m_pointer, &s_pointerListener, this);
    return m_unavailable;
}

void PointerLock::global(wl_registry *registry, uint32_t name, const char *interface, uint32_t)
{
    if (!strcmp(interface, zwp_pointer_constraints_v1_interface.name))
        m_constraints = static_cast<zwp_pointer_constraints_v1 *>(wl_registry_bind(registry, name, &zwp_pointer_constraints_v1_interface, 1));
    else if (!strcmp(interface, zwp_relative_pointer_manager_v1_interface.name))
        m_relativeManager = static_cast<zwp_relative_pointer_manager_v1 *>(wl_registry_bind(registry, name, &zwp_relative_pointer_manager_v1_interface, 1));
}

QString PointerLock::lock(QObject *windowObject, QObject *owner, bool unadjusted)
{
    if (const QString why = setUp(); !why.isEmpty()) return why;
    auto *window = qobject_cast<QWindow *>(windowObject);
    if (!window || !window->isActive() || !owner) return QStringLiteral("The page isn't in the active window.");
    if (!m_surface) return QStringLiteral("The mouse pointer isn't over the page.");
    // One lock at a time: a new request ends the one before.
    end(QString());

    m_owner = owner;
    m_window = window;
    m_unadjusted = unadjusted;
    m_dx = m_dy = 0;
    m_locked = zwp_pointer_constraints_v1_lock_pointer(m_constraints, m_surface, m_pointer, nullptr, ZWP_POINTER_CONSTRAINTS_V1_LIFETIME_ONESHOT);
    zwp_locked_pointer_v1_add_listener(m_locked, &s_lockedListener, this);
    m_relative = zwp_relative_pointer_manager_v1_get_relative_pointer(m_relativeManager, m_pointer);
    zwp_relative_pointer_v1_add_listener(m_relative, &s_relativeListener, this);
    connect(owner, &QObject::destroyed, this, [this] { end(QString()); });
    qApp->installEventFilter(this);
    m_timeout.start();
    Q_EMIT ownerChanged();
    return QString();
}

void PointerLock::unlock() { end(QString()); }

void PointerLock::lockActivated()
{
    if (!m_locked || m_active) return;
    m_timeout.stop();
    m_active = true;
    // The page draws its own pointer, if any.
    QGuiApplication::setOverrideCursor(QCursor(Qt::BlankCursor));
    m_cursorHidden = true;
    Q_EMIT locked(m_owner);
}

void PointerLock::lockDeactivated()
{
    // (A one-shot lock is over for good once the compositor ends it.)
    end(m_active ? QString() : QStringLiteral("The mouse pointer couldn't be locked."));
}

void PointerLock::relativeMotion(double dx, double dy, double dxRaw, double dyRaw)
{
    if (!m_active) return;
    m_dx += m_unadjusted ? dxRaw : dx;
    m_dy += m_unadjusted ? dyRaw : dy;
    if (!m_flush.isActive()) m_flush.start();
}

void PointerLock::flush()
{
    if (!m_active || (m_dx == 0 && m_dy == 0)) return;
    const double dx = m_dx, dy = m_dy;
    m_dx = m_dy = 0;
    Q_EMIT moved(dx, dy);
}

void PointerLock::end(const QString &why)
{
    if (!m_locked && !m_owner) return;
    m_flush.stop();
    m_timeout.stop();
    if (m_relative) { zwp_relative_pointer_v1_destroy(m_relative); m_relative = nullptr; }
    if (m_locked) { zwp_locked_pointer_v1_destroy(m_locked); m_locked = nullptr; }
    if (m_cursorHidden) { QGuiApplication::restoreOverrideCursor(); m_cursorHidden = false; }
    qApp->removeEventFilter(this);
    if (m_owner) disconnect(m_owner, &QObject::destroyed, this, nullptr);
    QObject *owner = m_owner;
    m_owner = nullptr;
    m_window = nullptr;
    m_active = false;
    m_dx = m_dy = 0;
    if (auto *wayland = qGuiApp->nativeInterface<QNativeInterface::QWaylandApplication>())
        wl_display_flush(wayland->display());
    Q_EMIT ownerChanged();
    Q_EMIT unlocked(owner, why);
}

// While locked: Esc lets go (as in other browsers; the page still gets the
// key), and so does the window losing focus.
bool PointerLock::eventFilter(QObject *watched, QEvent *event)
{
    switch (event->type()) {
    case QEvent::KeyPress:
        if (static_cast<QKeyEvent *>(event)->key() == Qt::Key_Escape) end(QString());
        break;
    case QEvent::WindowDeactivate:
        if (watched == m_window) end(QString());
        break;
    default:
        break;
    }
    return false;
}
